insert  into `tblcomplaintscode`(`id`,`Complaints_Code`,`Complete_Description`,`Priority_Status`) values (1,'AIRCON','Aircon','High'),(2,'Bathroom','Small space of bathroom','Medium'),(3,'TEST ONLY','ANG BAGAL NG INTERNET','Low'),(4,'LOW FOOT TRAFFIC LOW SALES','We have observed for awhile that we are running low in foot traffic that affects our sales. Asking for your support.','High Priority'),(5,'LOW FOOT TRAFIC LOW SALES','We have observed for awhile that we are running low with foot traffic that affects our sales. We are asking for your assistance on this.','High Priority');

/*Table structure for table `tblcondition` */

DROP TABLE IF EXISTS `tblcondition`;

CREATE TABLE `tblcondition` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `Term_ID` varchar(30) DEFAULT NULL,
  `Term_Name` varchar(200) DEFAULT NULL,
  `Description` mediumtext,
  `Group_ID` varchar(100) DEFAULT NULL,
  `Group_Name` varchar(100) DEFAULT NULL,
  `Stats` int(30) DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `id` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=latin1;

/*Data for the table `tblcondition` */

insert  into `tblcondition`(`id`,`Term_ID`,`Term_Name`,`Description`,`Group_ID`,`Group_Name`,`Stats`) values (1,'TRN-0000001','QUOTATION LETTER','Should you find the above proposal agreeable, kindly fax or send this letter to us with your signature on the space provided on or before ______________. Failure to respond on the said date will lead to CANCELLATION of your reserved booking. \n	FAX NUMBER	    : N/A\n	EMAIL ADDRESS   : kng@nccc.com.ph\n	OFFICE ADDRESS : Km. 7 Tigatto Road, Brgy.Buhangin Davao City \n\nAfter your confirmation, we shall then proceed with the preparation of our Memorandum of Agreement. \n \nShould you need further assistance, the undersigned may be reached at the following contact numbers: 221 – 6222 loc 2501 or at  mobile no.  0932-607-9534.','null','',1);

/*Table structure for table `tblcontract` */

DROP TABLE IF EXISTS `tblcontract`;

CREATE TABLE `tblcontract` (
  `id` int(30) NOT NULL AUTO_INCREMENT,
