/*Table structure for table `tblforzreading` */

DROP TABLE IF EXISTS `tblforzreading`;

CREATE TABLE `tblforzreading` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `Zreading` tinyint(5) DEFAULT '0',
  `Zreadingstat` tinyint(5) DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

/*Data for the table `tblforzreading` */

/*Table structure for table `tblgroups` */

DROP TABLE IF EXISTS `tblgroups`;

CREATE TABLE `tblgroups` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `Group_ID` varchar(30) NOT NULL,
  `Group_Name` varchar(100) DEFAULT NULL,
  `Status` varchar(1) DEFAULT '1',
  PRIMARY KEY (`Group_ID`),
  KEY `id` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

/*Data for the table `tblgroups` */

/*Table structure for table `tbllog_sheet` */

DROP TABLE IF EXISTS `tbllog_sheet`;

CREATE TABLE `tbllog_sheet` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `logID` varchar(30) DEFAULT NULL,
  `userid` varchar(30) DEFAULT NULL,
  `usertype` varchar(30) DEFAULT NULL,
  `xdatetime` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `action` varchar(30) DEFAULT NULL,
  `Machine_No` varchar(30) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2064 DEFAULT CHARSET=latin1;

