/*Table structure for table `tbltrans_company_owner_contacts` */

DROP TABLE IF EXISTS `tbltrans_company_owner_contacts`;

CREATE TABLE `tbltrans_company_owner_contacts` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `CompanyID` varchar(50) DEFAULT NULL,
  `type` varchar(10) DEFAULT NULL,
  `content` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

/*Data for the table `tbltrans_company_owner_contacts` */

/*Table structure for table `tbltrans_companysig` */

DROP TABLE IF EXISTS `tbltrans_companysig`;

CREATE TABLE `tbltrans_companysig` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `CompanyID` varchar(20) DEFAULT NULL,
  `firstname` varchar(40) DEFAULT NULL,
  `middlename` varchar(40) DEFAULT NULL,
  `lastname` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

/*Data for the table `tbltrans_companysig` */

/*Table structure for table `tbltrans_contractsigning` */

DROP TABLE IF EXISTS `tbltrans_contractsigning`;

CREATE TABLE `tbltrans_contractsigning` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `contractsigningID` varchar(20) DEFAULT NULL,
  `ProfileID` varchar(20) DEFAULT NULL,
  `LeadsName` varchar(20) DEFAULT NULL,
  `AssignedPerson` varchar(20) DEFAULT NULL,
  `Position` varchar(20) DEFAULT NULL,
  `Company_Name` varchar(20) DEFAULT NULL,
  `First_Name` varchar(20) DEFAULT NULL,
  `Middle_Name` varchar(20) DEFAULT NULL,
  `Last_Name` varchar(20) DEFAULT NULL,
  `Birthday` date DEFAULT NULL,
  `Mobile_No` varchar(11) DEFAULT NULL,
  `Telephone_No` varchar(20) DEFAULT NULL,
  `Email` varchar(20) DEFAULT NULL,
  `Website` varchar(20) DEFAULT NULL,
  `Remarks` varchar(20) DEFAULT NULL,
  `source` varchar(20) DEFAULT NULL,
  `Status` varchar(20) DEFAULT NULL,
  `Full_name` varchar(20) DEFAULT NULL,
  `xDATETIME` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

