/*Table structure for table `tbltrans_hierarchy_reqgroup` */

DROP TABLE IF EXISTS `tbltrans_hierarchy_reqgroup`;

CREATE TABLE `tbltrans_hierarchy_reqgroup` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `reqid` varchar(20) DEFAULT '',
