  CONSTRAINT `tbltrans_inquiry_unit_ibfk_1` FOREIGN KEY (`UnitID`) REFERENCES `tblref_unit` (`unitid`) ON DELETE NO ACTION ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=556 DEFAULT CHARSET=latin1;

