/*Table structure for table `view_beverage_charge` */

DROP TABLE IF EXISTS `view_beverage_charge`;

/*!50001 DROP VIEW IF EXISTS `view_beverage_charge` */;
/*!50001 DROP TABLE IF EXISTS `view_beverage_charge` */;

/*!50001 CREATE TABLE  `view_beverage_charge`(
 `Trans_Date` date ,
 `JDA_ID` varchar(40) ,
 `Tenant_ID` varchar(20) ,
 `tradename` varchar(100) ,
 `Trans_Code` varchar(30) ,
 `Trans_Desc` varchar(255) ,
 `Quantity` decimal(30,6) ,
 `Trans_Amount` decimal(30,6) ,
 `Trans_VAT` decimal(30,6) ,
 `Trans_TotAmount` decimal(30,6) ,
 `Reference` varchar(255) 
)*/;

/*Table structure for table `view_charges_escalation` */

DROP TABLE IF EXISTS `view_charges_escalation`;

/*!50001 DROP VIEW IF EXISTS `view_charges_escalation` */;
/*!50001 DROP TABLE IF EXISTS `view_charges_escalation` */;

/*!50001 CREATE TABLE  `view_charges_escalation`(
 `tenantId` varchar(20) ,
 `inquiryID` varchar(30) ,
 `tradename` varchar(100) ,
 `unitname` varchar(100) ,
 `chargeCode` varchar(30) ,
 `chargeDesc` varchar(50) ,
 `chargeType` varchar(20) ,
 `chargeAmount` decimal(30,4) ,
 `EscaStartDate` date ,
 `EscaEndDate` date ,
 `escaYear` varchar(30) ,
 `EscaRate` decimal(30,4) ,
 `EscaAmount` decimal(30,4) ,
 `EscaTotal` decimal(30,4) ,
 `Mall_ID` varchar(20) ,
 `Mall_Name` varchar(100) 
)*/;

/*Table structure for table `view_rent_escalation` */

DROP TABLE IF EXISTS `view_rent_escalation`;

/*!50001 DROP VIEW IF EXISTS `view_rent_escalation` */;
/*!50001 DROP TABLE IF EXISTS `view_rent_escalation` */;

/*!50001 CREATE TABLE  `view_rent_escalation`(
 `TenantID` varchar(20) ,
 `InquiryID` varchar(20) ,
 `tradename` varchar(100) ,
 `billingtype` varchar(30) ,
 `billingperc` varchar(30) ,
 `datefrom` date ,
 `dateto` date ,
 `EscaYear` varchar(20) ,
 `monthly_dues` decimal(40,6) ,
 `Sdate` date ,
 `Edate` date ,
 `EscaRate` decimal(30,4) ,
 `EscaAmount` decimal(30,4) ,
 `EscaTotal` decimal(30,4) ,
 `ProposalNum` tinyint(5) 
)*/;

/*View structure for view view_beverage_charge */

/*!50001 DROP TABLE IF EXISTS `view_beverage_charge` */;
/*!50001 DROP VIEW IF EXISTS `view_beverage_charge` */;

/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`gates`@`%` SQL SECURITY DEFINER VIEW `view_beverage_charge` AS (select `a`.`Trans_Date` AS `Trans_Date`,`a`.`TenantID` AS `JDA_ID`,`b`.`TenantID` AS `Tenant_ID`,`b`.`tradename` AS `tradename`,`a`.`Trans_Code` AS `Trans_Code`,`a`.`Trans_Desc` AS `Trans_Desc`,`a`.`Quantity` AS `Quantity`,`a`.`Trans_Amount` AS `Trans_Amount`,`a`.`Trans_VAT` AS `Trans_VAT`,`a`.`Trans_TotAmount` AS `Trans_TotAmount`,`a`.`Reference` AS `Reference` from (`tbltrans_bevlist` `a` join `tbltrans_tenants` `b`) where (`a`.`TenantID` = `b`.`JDATenant_Code`)) */;

/*View structure for view view_charges_escalation */

/*!50001 DROP TABLE IF EXISTS `view_charges_escalation` */;
/*!50001 DROP VIEW IF EXISTS `view_charges_escalation` */;

/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`gates`@`%` SQL SECURITY DEFINER VIEW `view_charges_escalation` AS (select `c`.`TenantID` AS `tenantId`,`a`.`InquiryID` AS `inquiryID`,`c`.`tradename` AS `tradename`,`d`.`unitname` AS `unitname`,`a`.`ChargeCode` AS `chargeCode`,`a`.`ChargeDesc` AS `chargeDesc`,`a`.`ChargeType` AS `chargeType`,`a`.`ChargeAmount` AS `chargeAmount`,`b`.`EscaStartDate` AS `EscaStartDate`,`b`.`EscaEndDate` AS `EscaEndDate`,`b`.`EscaYear` AS `escaYear`,`b`.`EscaRate` AS `EscaRate`,`b`.`EscaAmount` AS `EscaAmount`,`b`.`EscaTotal` AS `EscaTotal`,`c`.`mallID` AS `Mall_ID`,`e`.`mallname` AS `Mall_Name` from ((((`tbltrans_procharges` `a` join `tbltrans_chargeesca_br` `b`) join `tbltrans_tenants` `c`) join `tblref_unit` `d`) join `tblref_mall` `e`) where ((`a`.`InquiryID` = `b`.`InquiryID`) and (`a`.`ChargeCode` = `b`.`ChargeCode`) and (`d`.`unitid` = `b`.`UnitID`) and (`a`.`InquiryID` = `c`.`inqID`) and (`c`.`mallID` = `e`.`mallid`) and (`b`.`EscaStartDate` is not null) and (`b`.`EscaEndDate` is not null))) */;

/*View structure for view view_rent_escalation */

/*!50001 DROP TABLE IF EXISTS `view_rent_escalation` */;
/*!50001 DROP VIEW IF EXISTS `view_rent_escalation` */;

/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`gates`@`%` SQL SECURITY DEFINER VIEW `view_rent_escalation` AS (select `b`.`TenantID` AS `TenantID`,`a`.`InquiryID` AS `InquiryID`,`b`.`tradename` AS `tradename`,`c`.`billingtype` AS `billingtype`,`c`.`billingperc` AS `billingperc`,`b`.`datefrom` AS `datefrom`,`b`.`dateto` AS `dateto`,`a`.`EscaYear` AS `EscaYear`,`c`.`monthly_dues` AS `monthly_dues`,`a`.`EscaStartDate` AS `Sdate`,`a`.`EscaEndDate` AS `Edate`,`a`.`EscaRate` AS `EscaRate`,`a`.`EscaAmount` AS `EscaAmount`,`a`.`EscaTotal` AS `EscaTotal`,`a`.`ProposalNum` AS `ProposalNum` from ((`tbltrans_escalation` `a` join `tbltrans_tenants` `b`) join `tbltrans_inquiry` `c`) where ((`b`.`inqID` = `c`.`Inquiry_ID`) and (`b`.`inqID` = `a`.`InquiryID`)) order by `b`.`TenantID`,`a`.`EscaYear`) */;

